WITH metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY country ORDER BY credit_limit, id) AS credit_limit_bucket, ROUND(age / SUM(age) OVER (PARTITION BY country), 4) AS age_share, NTILE(5) OVER (PARTITION BY segment ORDER BY credit_limit, id) AS credit_limit_bucket_2, SUM(age) OVER (PARTITION BY city, country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_age, CORR(credit_limit, age) OVER (PARTITION BY city) AS corr_credit_limit_age FROM customers) SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, COUNT_IF(city = 'London') AS london_events, AVG(cumulative_age) FILTER (WHERE segment = 'Corporate') AS corporate_avg_cumulative_age, MAX(credit_limit_bucket_2) AS max_credit_limit_bucket_2 FROM metrics GROUP BY DATE_TRUNC('YEAR', signup_date) ORDER BY year_start DESC;
